      'pl': 'INTELIGENCJA INWESTYCJI W NIERUCHOMOŚCI',
      'ro': 'INTELIGENȚĂ PRIVIND INVESTIȚIILE IMOBILIARE',
      'ta': 'சொத்து முதலீட்டு நுண்ணறிவு',
      'tr': 'GAYRİMENKUL YATIRIM İSTİHBARATI',
      'ur': 'پراپرٹی انویسٹمنٹ انٹیلی جنس',
      'zh_Hant': '房地產投資情報',
    },
    'smzmhxaq': {
      'en':
          'Stay ahead of the curve with our carefully curated insights into the rental market, property investment trends, and legislative changes affecting landlords across England.',
      'ar':
          'ابقَ على اطلاع دائم بأحدث التطورات من خلال رؤانا المدروسة بعناية حول سوق الإيجار، واتجاهات الاستثمار العقاري، والتغييرات التشريعية التي تؤثر على الملاك في جميع أنحاء إنجلترا.',
      'bn':
          'ইংল্যান্ড জুড়ে বাড়িওয়ালাদের প্রভাবিত করে ভাড়া বাজার, সম্পত্তি বিনিয়োগের প্রবণতা এবং আইনী পরিবর্তন সম্পর্কে আমাদের সাবধানে সংগৃহীত অন্তর্দৃষ্টি দিয়ে এগিয়ে থাকুন।',
      'de':
          'Bleiben Sie immer einen Schritt voraus mit unseren sorgfältig zusammengestellten Einblicken in den Mietmarkt, Immobilieninvestitionstrends und Gesetzesänderungen, die Vermieter in ganz England betreffen.',
      'es':
          'Manténgase a la vanguardia con nuestros conocimientos cuidadosamente seleccionados sobre el mercado de alquiler, las tendencias de inversión inmobiliaria y los cambios legislativos que afectan a los propietarios en toda Inglaterra.',
      'fr':
          'Gardez une longueur d\'avance grâce à nos analyses pointues du marché locatif, des tendances en matière d\'investissement immobilier et des changements législatifs qui affectent les propriétaires en Angleterre.',
      'gu':
          'ભાડા બજાર, મિલકત રોકાણના વલણો અને સમગ્ર ઈંગ્લેન્ડમાં મકાનમાલિકોને અસર કરતા કાયદાકીય ફેરફારો વિશે અમારી કાળજીપૂર્વક તૈયાર કરેલી આંતરદૃષ્ટિ સાથે આગળ રહો.',
      'hi':
          'किराये के बाजार, संपत्ति निवेश के रुझानों और इंग्लैंड भर में मकान मालिकों को प्रभावित करने वाले विधायी परिवर्तनों के बारे में हमारे सावधानीपूर्वक संकलित जानकारियों के साथ नवीनतम जानकारी से अवगत रहें।',
      'nl':
          'Blijf de ontwikkelingen een stap voor met onze zorgvuldig samengestelde inzichten in de huurmarkt, trends in vastgoedinvesteringen en wetswijzigingen die van invloed zijn op verhuurders in heel Engeland.',
      'pa':
          'ਇੰਗਲੈਂਡ ਭਰ ਵਿੱਚ ਮਕਾਨ ਮਾਲਕਾਂ ਨੂੰ ਪ੍ਰਭਾਵਿਤ ਕਰਨ ਵਾਲੇ ਕਿਰਾਏ ਦੇ ਬਾਜ਼ਾਰ, ਜਾਇਦਾਦ ਨਿਵੇਸ਼ ਦੇ ਰੁਝਾਨਾਂ ਅਤੇ ਵਿਧਾਨਕ ਤਬਦੀਲੀਆਂ ਬਾਰੇ ਸਾਡੀਆਂ ਧਿਆਨ ਨਾਲ ਤਿਆਰ ਕੀਤੀਆਂ ਸੂਝਾਂ ਨਾਲ ਅੱਗੇ ਰਹੋ।',
      'pl':
          'Bądź na bieżąco dzięki naszym starannie opracowanym informacjom na temat rynku wynajmu, trendów w inwestowaniu w nieruchomości i zmian prawnych mających wpływ na właścicieli nieruchomości w całej Anglii.',
      'ro':
          'Fiți cu un pas înainte cu ajutorul informațiilor noastre atent selecționate despre piața închirierilor, tendințele investițiilor imobiliare și modificările legislative care afectează proprietarii din Anglia.',
      'ta':
          'இங்கிலாந்து முழுவதும் உள்ள நில உரிமையாளர்களைப் பாதிக்கும் வாடகை சந்தை, சொத்து முதலீட்டுப் போக்குகள் மற்றும் சட்ட மாற்றங்கள் பற்றிய எங்கள் கவனமாகத் தொகுக்கப்பட்ட நுண்ணறிவுகளுடன் முன்னேறிச் செல்லுங்கள்.',
      'tr':
          'İngiltere genelindeki ev sahiplerini etkileyen kiralama piyasası, gayrimenkul yatırım trendleri ve yasal değişikliklere dair özenle derlenmiş bilgilerimizle her zaman bir adım önde olun.',
      'ur':
          'رینٹل مارکیٹ، جائیداد کی سرمایہ کاری کے رجحانات، اور پورے انگلینڈ میں زمینداروں کو متاثر کرنے والی قانون سازی کی تبدیلیوں کے بارے میں ہماری احتیاط سے تیار کردہ بصیرت کے ساتھ وکر سے آگے رہیں۔',
      'zh_Hant': '透過我們精心整理的關於英格蘭各地租賃市場、房地產投資趨勢和影響房東的立法變化的見解，保持領先地位。',
    },
