    '8eywg1k3': {
      'en':
          'To help us track your goals, please enter the outstanding mortgage amount on the following properties. Remember, all fields are optional and can be updated anytime.',
      'ar':
          'لمساعدتنا في تتبع أهدافك، يُرجى إدخال مبلغ الرهن العقاري المتبقي على العقارات التالية. تذكر أن جميع الحقول اختيارية ويمكن تحديثها في أي وقت.',
      'bn':
          'আপনার লক্ষ্যগুলি ট্র্যাক করতে আমাদের সাহায্য করার জন্য, অনুগ্রহ করে নিম্নলিখিত সম্পত্তিগুলিতে বকেয়া বন্ধকের পরিমাণ লিখুন। মনে রাখবেন, সমস্ত ক্ষেত্র ঐচ্ছিক এবং যেকোনো সময় আপডেট করা যেতে পারে।',
      'de':
          'Um uns bei der Verfolgung Ihrer Ziele zu unterstützen, geben Sie bitte die ausstehenden Hypothekenbeträge der folgenden Immobilien an. Alle Felder sind optional und können jederzeit aktualisiert werden.',
      'es':
          'Para ayudarnos a monitorear sus objetivos, ingrese el monto de la hipoteca pendiente de las siguientes propiedades. Recuerde que todos los campos son opcionales y se pueden actualizar en cualquier momento.',
      'fr':
          'Pour nous aider à suivre vos objectifs, veuillez indiquer le solde hypothécaire des propriétés suivantes. Notez que tous les champs sont facultatifs et peuvent être modifiés à tout moment.',
      'gu':
          'તમારા લક્ષ્યોને ટ્રેક કરવામાં અમારી મદદ કરવા માટે, કૃપા કરીને નીચેની મિલકતો પર બાકી મોર્ટગેજ રકમ દાખલ કરો. યાદ રાખો, બધા ફીલ્ડ વૈકલ્પિક છે અને ગમે ત્યારે અપડેટ કરી શકાય છે.',
      'hi':
          'हमें आपके लक्ष्यों को ट्रैक करने में मदद करने के लिए, कृपया निम्नलिखित संपत्तियों पर बकाया बंधक राशि दर्ज करें। ध्यान रखें, सभी फ़ील्ड वैकल्पिक हैं और इन्हें किसी भी समय अपडेट किया जा सकता है।',
      'nl':
          'Om ons te helpen uw doelen te volgen, vragen we u het openstaande hypotheekbedrag van de volgende panden in te vullen. Houd er rekening mee dat alle velden optioneel zijn en op elk moment kunnen worden bijgewerkt.',
      'pa':
          'ਤੁਹਾਡੇ ਟੀਚਿਆਂ ਨੂੰ ਟਰੈਕ ਕਰਨ ਵਿੱਚ ਸਾਡੀ ਮਦਦ ਕਰਨ ਲਈ, ਕਿਰਪਾ ਕਰਕੇ ਹੇਠ ਲਿਖੀਆਂ ਜਾਇਦਾਦਾਂ \'ਤੇ ਬਕਾਇਆ ਮੌਰਗੇਜ ਰਕਮ ਦਰਜ ਕਰੋ। ਯਾਦ ਰੱਖੋ, ਸਾਰੇ ਖੇਤਰ ਵਿਕਲਪਿਕ ਹਨ ਅਤੇ ਕਿਸੇ ਵੀ ਸਮੇਂ ਅੱਪਡੇਟ ਕੀਤੇ ਜਾ ਸਕਦੇ ਹਨ।',
      'pl':
          'Aby ułatwić nam śledzenie Twoich celów, wprowadź kwotę pozostałego kredytu hipotecznego dla poniższych nieruchomości. Pamiętaj, że wszystkie pola są opcjonalne i można je w dowolnym momencie zaktualizować.',
      'ro':
          'Pentru a ne ajuta să vă urmărim obiectivele, vă rugăm să introduceți suma ipotecii restante pentru următoarele proprietăți. Rețineți că toate câmpurile sunt opționale și pot fi actualizate oricând.',
      'ta':
          'உங்கள் இலக்குகளைக் கண்காணிக்க எங்களுக்கு உதவ, பின்வரும் சொத்துக்களில் நிலுவையில் உள்ள அடமானத் தொகையை உள்ளிடவும். நினைவில் கொள்ளுங்கள், அனைத்து புலங்களும் விருப்பத்திற்குரியவை மற்றும் எந்த நேரத்திலும் புதுப்பிக்கப்படலாம்.',
      'tr':
          'Hedeflerinizi takip edebilmemiz için lütfen aşağıdaki mülkler üzerindeki ödenmemiş ipotek tutarlarını girin. Tüm alanların isteğe bağlı olduğunu ve istediğiniz zaman güncellenebileceğini unutmayın.',
      'ur':
          'اپنے اہداف کو ٹریک کرنے میں ہماری مدد کے لیے، براہ کرم درج ذیل پراپرٹیز پر رہن کی بقایا رقم درج کریں۔ یاد رکھیں، تمام فیلڈز اختیاری ہیں اور انہیں کسی بھی وقت اپ ڈیٹ کیا جا سکتا ہے۔',
      'zh_Hant': '為了幫助我們追蹤您的目標，請填寫以下房產的未償還房貸金額。請注意，所有欄位均為選填項，您可以隨時更新。',
    },
